<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { adminApi, adminSession, type AdminUser, type RegistrationSettings, type ReservedUsername } from '@/api/admin'
import { useLocaleStore } from '@/stores/locale'

const router = useRouter(); const locale = useLocaleStore(); const t = locale.translate; const users = ref<AdminUser[]>([]); const total = ref(0); const search = ref(''); const status = ref(''); const role = ref(''); const offset = ref(0); const pageSize = 50; const registration = ref<RegistrationSettings | null>(null); const globalLimit = ref(20); const reserved = ref<ReservedUsername[]>([]); const reservedName = ref(''); const error = ref('')
async function loadUsers(){ const q=new URLSearchParams({limit:String(pageSize),offset:String(offset.value)});if(search.value)q.set('search',search.value);if(status.value)q.set('status',status.value);if(role.value)q.set('role',role.value);const result=await adminApi.users(q.toString());if(result.total > 0 && offset.value >= result.total){offset.value=Math.max(0,Math.floor((result.total-1)/pageSize)*pageSize);return loadUsers()}users.value=result.users;total.value=result.total }
async function load(){try{await Promise.all([loadUsers(),adminApi.registration().then(v=>registration.value=v),adminApi.limits().then(v=>globalLimit.value=v.max_cloud_projects),adminApi.reserved().then(v=>reserved.value=v)])}catch(e){error.value=e instanceof Error?e.message:'Ошибка загрузки'}}
async function action(user:AdminUser, action:'approve'|'reject'|'block'|'unblock'|'revoke'){if(!confirm(`Подтвердить действие: ${action}?`))return; if(action==='revoke')await adminApi.revoke(user.id);else await adminApi.lifecycle(user.id,action);await loadUsers()}
async function saveRegistration(){if(registration.value)registration.value=await adminApi.saveRegistration({mode:registration.value.mode,max_users:registration.value.max_users})}
async function saveLimit(){await adminApi.saveLimits(globalLimit.value)}
async function setOverride(user:AdminUser){const raw=prompt('Лимит проектов (пусто — наследовать):',user.max_cloud_projects_override?.toString()??'');if(raw===null)return;await adminApi.userLimit(user.id,raw.trim()===''?null:Number(raw));await loadUsers()}
async function addReserved(){if(!reservedName.value.trim())return;await adminApi.addReserved(reservedName.value);reservedName.value='';reserved.value=await adminApi.reserved()}
async function removeReserved(name:string){if(confirm(`Удалить резервирование ${name}?`)){await adminApi.removeReserved(name);reserved.value=await adminApi.reserved()}}
async function logout(){try{await adminSession.logout()}finally{router.replace('/admin/login')}}
function applyFilters(){offset.value=0;void loadUsers()}
function previous(){offset.value=Math.max(0,offset.value-pageSize);void loadUsers()}
function next(){if(offset.value+pageSize<total.value){offset.value+=pageSize;void loadUsers()}}
onMounted(load)
</script>
<template><main class="admin"><header><h1>{{t('Администрирование')}}</h1><button class="nf-button" @click="logout">{{t('Выйти')}}</button></header><p v-if="error" role="alert">{{error}}</p><section><h2>{{t('Пользователи')}} ({{total}})</h2><form @submit.prevent="applyFilters"><input v-model="search" :aria-label="t('Поиск')" :placeholder="t('Поиск')"/><select v-model="status" :aria-label="t('Статус')"><option value="">{{t('Все статусы')}}</option><option>pending</option><option>active</option><option>rejected</option><option>blocked</option></select><select v-model="role" :aria-label="t('Роль')"><option value="">{{t('Все роли')}}</option><option>user</option><option>admin</option></select><button>{{t('Найти')}}</button></form><table><thead><tr><th>{{t('Пользователь')}}</th><th>{{t('Статус')}}</th><th>{{t('Лимит')}}</th><th>{{t('Действия')}}</th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td>{{user.username}}<br/><small>{{user.email}} · {{user.role}} · {{user.email_verified?t('email подтверждён'):t('email не подтверждён')}}</small></td><td>{{user.status}}</td><td>{{user.effective_max_cloud_projects}} <small>{{user.max_cloud_projects_override===null?t('(общий)'):t('(override)')}}</small></td><td v-if="user.role==='admin'">{{t('Защищён')}}</td><td v-else><button v-if="user.status==='pending'||user.status==='rejected'" @click="action(user,'approve')">{{t('Одобрить')}}</button><button v-if="user.status==='pending'" @click="action(user,'reject')">{{t('Отклонить')}}</button><button v-if="user.status==='active'" @click="action(user,'block')">{{t('Блокировать')}}</button><button v-if="user.status==='blocked'" @click="action(user,'unblock')">{{t('Разблокировать')}}</button><button @click="action(user,'revoke')">{{t('Сессии')}}</button><button @click="setOverride(user)">{{t('Лимит')}}</button></td></tr></tbody></table><nav :aria-label="t('Пагинация')"><button :disabled="offset===0" @click="previous">{{t('Назад')}}</button><span>{{total===0?0:offset+1}}–{{Math.min(offset+pageSize,total)}} / {{total}}</span><button :disabled="offset+pageSize>=total" @click="next">{{t('Далее')}}</button></nav></section><section v-if="registration"><h2>{{t('Регистрация')}}</h2><select v-model="registration.mode"><option value="open">{{t('Открытая')}}</option><option value="approval">{{t('По одобрению')}}</option><option value="closed">{{t('Закрытая')}}</option></select><label>{{t('Максимум пользователей')}} <input v-model.number="registration.max_users" type="number" min="0" /></label><small>{{t('Активных')}}: {{registration.active_users}}. {{t('Уменьшение не отключает существующие аккаунты.')}}</small><button @click="saveRegistration">{{t('Сохранить')}}</button></section><section><h2>{{t('Лимиты')}}</h2><label>{{t('Максимум cloud-проектов')}} <input v-model.number="globalLimit" type="number" min="0"/></label><button @click="saveLimit">{{t('Сохранить')}}</button></section><section><h2>{{t('Зарезервированные имена')}}</h2><form @submit.prevent="addReserved"><input v-model="reservedName" :aria-label="t('Имя')"/><button>{{t('Добавить')}}</button></form><ul><li v-for="item in reserved" :key="item.username_normalized">{{item.username_normalized}} <button @click="removeReserved(item.username_normalized)">{{t('Удалить')}}</button></li></ul></section></main></template>
<style scoped>.admin{max-width:75rem;margin:auto;padding:1.5rem;display:grid;gap:2rem}.admin header{display:flex;justify-content:space-between;align-items:center}section{display:grid;gap:.75rem}table{width:100%;border-collapse:collapse}td,th{padding:.5rem;border-bottom:1px solid var(--nf-color-border);text-align:left;vertical-align:top}button{margin:.15rem}input,select{padding:.45rem}</style>
